# ── Context Managers ───────────────────────────────────────────────────────────

def context_manager(func: Callable[..., Optional[Awaitable[T]]]) -> Callable[..., T]:

    def wrapper(*args, **kwargs) -> T:
        with ContextManager() as cm:
            result = func(*args, **kwargs)
            if result is not None:
                yield result
            else:
                yield cm.result()

    return wrapper


